const SUPABASE_CONFIG={url:'https://dmwbxlzjmptefddasgbe.supabase.co',anonKey:'sb_publishable_lzqPmG4aS6MQIVb0M-0sZw_u9j7TiyT'};
let sb=null,cloudUser=null,cloudState=null,cloudSaveTimer=null;
const PHOTO_BUCKET='recipe-images';
const photoUrlCache={};
function supabaseConfigured(){return SUPABASE_CONFIG.url.startsWith('https://')&&!SUPABASE_CONFIG.url.includes('PASTE_')&&SUPABASE_CONFIG.anonKey&&!SUPABASE_CONFIG.anonKey.includes('PASTE_')}
function localState(){let parse=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}};return {custom_recipes:parse('cookCustom',[]),favorites:parse('cookFav',[]),photos:parse('cookPhotos',{}),language:localStorage.getItem('cookLang')||'cs',updated_at:new Date().toISOString()}}
function applyState(st){cloudState=st||localState();localStorage.setItem('cookCustom',JSON.stringify(cloudState.custom_recipes||[]));localStorage.setItem('cookFav',JSON.stringify(cloudState.favorites||[]));localStorage.setItem('cookPhotos',JSON.stringify(cloudState.photos||{}));if(cloudState.language)localStorage.setItem('cookLang',cloudState.language)}
function isDataImage(v){return typeof v==='string'&&v.startsWith('data:image/')}
function photoPath(v){return v&&typeof v==='object'?v.path:null}
async function refreshPhotoUrls(){if(!sb||!cloudUser)return;const photos=photoOverrides();for(const [id,v] of Object.entries(photos)){const path=photoPath(v);if(!path)continue;const {data,error}=await sb.storage.from(PHOTO_BUCKET).createSignedUrl(path,60*60*24*30);if(!error&&data?.signedUrl)photoUrlCache[id]=data.signedUrl}}
async function dataUrlToBlob(dataUrl){const res=await fetch(dataUrl);return await res.blob()}
async function uploadPhotoToStorage(id,blob){if(!sb||!cloudUser)throw new Error('Sign in first');const old=photoOverrides()[id],oldPath=photoPath(old);const path=`${cloudUser.id}/${id}-${Date.now()}.jpg`;const {error}=await sb.storage.from(PHOTO_BUCKET).upload(path,blob,{contentType:'image/jpeg',upsert:false,cacheControl:'3600'});if(error)throw error;if(oldPath)await sb.storage.from(PHOTO_BUCKET).remove([oldPath]);const {data,error:urlError}=await sb.storage.from(PHOTO_BUCKET).createSignedUrl(path,60*60*24*30);if(urlError)throw urlError;photoUrlCache[id]=data.signedUrl;setPhotoOverride(id,{path});return path}
async function migrateLegacyPhotos(){if(!sb||!cloudUser)return;const photos={...photoOverrides()};let changed=false;for(const [id,v] of Object.entries(photos)){if(!isDataImage(v))continue;try{const blob=await dataUrlToBlob(v);const path=`${cloudUser.id}/${id}-${Date.now()}.jpg`;const {error}=await sb.storage.from(PHOTO_BUCKET).upload(path,blob,{contentType:'image/jpeg',upsert:false,cacheControl:'3600'});if(error)throw error;photos[id]={path};changed=true}catch(e){console.error('Photo migration failed',id,e)}}if(changed){localStorage.setItem('cookPhotos',JSON.stringify(photos));if(cloudState)cloudState.photos=photos;await refreshPhotoUrls();await saveCloudState(true);toast('Fotografie byly přesunuty do Supabase Storage')}}
function updateCloudStatus(){const el=document.getElementById('cloudStatus'),btn=document.getElementById('cloudBtn');if(!el)return;if(!supabaseConfigured()){el.textContent='⚙️ Setup needed';btn.textContent='☁️ Setup Supabase'}else if(cloudUser){el.textContent='☁️ '+cloudUser.email;btn.textContent='☁️ Account'}else{el.textContent='Local only';btn.textContent='☁️ Sign in'}}
function loadScript(src){return new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.async=true;el.onload=resolve;el.onerror=()=>reject(new Error('Nelze načíst '+src));document.head.appendChild(el)})}
async function ensureSupabaseSdk(){if(window.supabase?.createClient)return true;const sources=['https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2','https://unpkg.com/@supabase/supabase-js@2'];for(const src of sources){try{await loadScript(src);if(window.supabase?.createClient)return true}catch(e){console.warn(e)}}return false}
function authBaseUrl(){return location.protocol==='http:'||location.protocol==='https:'?location.origin+location.pathname:undefined}
function setAuthMessage(message,type='info'){const el=document.getElementById('authMessage');if(!el)return;el.textContent=message;el.className='auth-state '+type}
function friendlyAuthError(error){const raw=error?.message||String(error||'');const m=raw.toLowerCase();if(m.includes('invalid login credentials'))return msg('Nesprávný e-mail nebo heslo.','Incorrect email or password.','メールアドレスまたはパスワードが正しくありません。');if(m.includes('email not confirmed'))return msg('E-mail ještě není potvrzený.','Your email is not confirmed yet.','メールアドレスの確認が完了していません。');if(m.includes('user already registered'))return msg('Účet s tímto e-mailem už existuje.','An account with this email already exists.','このメールアドレスのアカウントはすでに存在します。');if(m.includes('password should be'))return msg(msg('Heslo musí mít alespoň 6 znaků.','Password must contain at least 6 characters.','パスワードは6文字以上にしてください。'),'Password must contain at least 6 characters.','パスワードは6文字以上にしてください。');if(m.includes('failed to fetch')||m.includes('network'))return msg('Nepodařilo se připojit k Supabase.','Could not connect to Supabase.','Supabaseに接続できませんでした。');return raw||msg('Neznámá chyba.','Unknown error.','不明なエラーです。')}
async function initSupabase(){try{if(!supabaseConfigured()){updateCloudStatus();return}const sdkReady=await ensureSupabaseSdk();if(!sdkReady){updateCloudStatus();setAuthMessage(msg('Knihovna Supabase se nenačetla.','The Supabase library could not be loaded.','Supabaseライブラリを読み込めませんでした。インターネット接続を確認してください。'),'error');return}sb=window.supabase.createClient(SUPABASE_CONFIG.url,SUPABASE_CONFIG.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});const {data,error}=await sb.auth.getSession();if(error)throw error;cloudUser=data.session?.user||null;if(cloudUser)await loadCloudState();sb.auth.onAuthStateChange((_event,session)=>{setTimeout(async()=>{cloudUser=session?.user||null;if(cloudUser)await loadCloudState();else{cloudState=null;applyState(localState());render()}updateCloudStatus()},0)});updateCloudStatus()}catch(e){console.error('Supabase init failed',e);setAuthMessage('Supabase se nepodařilo spustit: '+friendlyAuthError(e),'error');updateCloudStatus()}}
async function loadCloudState(){if(!sb||!cloudUser)return;const {data,error}=await sb.from('cookbook_state').select('*').eq('user_id',cloudUser.id).maybeSingle();if(error){console.error(error);toast('Cloud load error');return}if(data){applyState(data);lang=data.language||lang;document.getElementById('language').value=lang;applyLanguage()}else{cloudState=localState();await saveCloudState(true)}await migrateLegacyPhotos();await refreshPhotoUrls();render();updateCloudStatus()}
async function saveCloudState(immediate=false){if(!cloudUser||!sb)return;clearTimeout(cloudSaveTimer);const run=async()=>{const st=localState();cloudState=st;const payload={user_id:cloudUser.id,custom_recipes:st.custom_recipes,favorites:st.favorites,photos:st.photos,language:localStorage.getItem('cookLang')||'cs',updated_at:new Date().toISOString()};const {error}=await sb.from('cookbook_state').upsert(payload,{onConflict:'user_id'});if(error){console.error(error);toast('Cloud save error')}else updateCloudStatus()};if(immediate)await run();else cloudSaveTimer=setTimeout(run,500)}
function cloudChanged(){saveCloudState(false)}

