function t(k){return UI[lang][k]||UI.cs[k]||k}
function msg(cs,en,ja){return lang==='ja'?ja:lang==='en'?en:cs}
function customRecipes(){if(cloudUser&&cloudState)return cloudState.custom_recipes||[];try{return JSON.parse(localStorage.getItem('cookCustom')||'[]')}catch{return []}}
function allRecipes(){return [...baseRecipes,...customRecipes()]}
function favs(){if(cloudUser&&cloudState)return cloudState.favorites||[];try{return JSON.parse(localStorage.getItem('cookFav')||'[]')}catch{return []}}
function photoOverrides(){if(cloudUser&&cloudState)return cloudState.photos||{};try{return JSON.parse(localStorage.getItem('cookPhotos')||'{}')}catch{return {}}}
function setPhotoOverride(id,data){const p={...photoOverrides()};if(data)p[id]=data;else delete p[id];localStorage.setItem('cookPhotos',JSON.stringify(p));if(cloudState)cloudState.photos=p;cloudChanged()}
function imageFor(r){const v=photoOverrides()[r.id];return photoUrlCache[r.id]||(isDataImage(v)?v:null)||r.image||defaultPhotos[r.kind]||defaultPhotos['Snídaně']}
function chapterName(c){return lang==='cs'?c:(CHAPTERS[c]?.[lang]||c)}
