function jaTranslate(s){if(!s)return '';if(JA_EXACT[s])return JA_EXACT[s];let out=s;for(const [a,b] of JA_ACTIONS)out=out.replaceAll(a,b);for(const [a,b] of JA_WORDS)out=out.replaceAll(a,b);out=out.replaceAll('minut','分').replaceAll('minuty','分').replaceAll('hodin','時間').replaceAll('hodiny','時間').replaceAll('v lednici','冷蔵庫で').replaceAll('přes noc','一晩').replaceAll('na 180 °C','180°Cで').replaceAll('při 180 °C','180°Cで').replaceAll('na 170 °C','170°Cで').replaceAll('dozlatova','きつね色になるまで').replaceAll('podle chuti','好みの量').replaceAll('malé kostičky','小さな角切り').replaceAll('do hladkého těsta','なめらかな生地になるまで').replaceAll('do misky','ボウルに').replaceAll('do formy','型に').replaceAll('na nepřilnavé pánvi','フッ素加工のフライパンで').replaceAll('na mírném ohni','弱火で').replaceAll('ihned','すぐに');
// If any Czech-specific characters remain, remove the Czech fragment instead of showing a half-translated UI.
out=out.replace(/[A-Za-zÀ-ž]+/g,m=>{const ok=/^(g|ml|kg|kcal|min|AEON|Seiyu|Life|Costco|Oikos|Gyomu|Super|Ito|Yokado|Don|Quijote|Amazon|Japan|iHerb|konbini|plain|light|matcha|tofu|natto|kimchi|edamame|psyllium|erythritol)$/i.test(m);return ok?m:''}).replace(/\s{2,}/g,' ').replace(/^[\s,.;:]+|[\s,.;:]+$/g,'');
return out||'詳しい内容はレシピの分量を確認してください。'}

function trLine(s){if(lang==='cs')return s;if(lang==='ja')return jaTranslate(s);const dictEn={'Smíchej':'Mix','Přidej':'Add','Vmíchej':'Fold in','Rozmixuj':'Blend','Nalij':'Pour','Peč':'Bake','Nech':'Leave','Podávej':'Serve','Připrav':'Prepare','Nakrájej':'Cut','Rozmačkej':'Mash','Opékej':'Cook','Uchovávej':'Store','Zakryj':'Cover','Ráno':'In the morning','vejce':'eggs','vejce.':'eggs.','řeckého jogurtu':'Greek yogurt','proteinu':'protein powder','proteinového prášku':'protein powder','ovesných vloček':'oats','vloček':'oats','borůvek':'blueberries','mléka':'milk','cukety':'zucchini','prášku do pečiva':'baking powder','skořice':'cinnamon','špetka soli':'a pinch of salt','podle chuti':'to taste','minut':'minutes','hodin':'hours','v lednici':'in the refrigerator','na 180 °C':'at 180°C','na 170 °C':'at 170°C'};const dictJa={'Smíchej':'混ぜる','Přidej':'加える','Vmíchej':'混ぜ込む','Rozmixuj':'ブレンダーで混ぜる','Nalij':'流し入れる','Peč':'焼く','Nech':'置く','Podávej':'盛り付ける','Připrav':'準備する','Nakrájej':'切る','Rozmačkej':'つぶす','Opékej':'焼く','Uchovávej':'保存する','Zakryj':'ふたをする','Ráno':'朝に','řeckého jogurtu':'ギリシャヨーグルト','proteinu':'プロテインパウダー','proteinového prášku':'プロテインパウダー','ovesných vloček':'オートミール','vloček':'オートミール','borůvek':'ブルーベリー','mléka':'ミルク','cukety':'ズッキーニ','prášku do pečiva':'ベーキングパウダー','skořice':'シナモン','špetka soli':'塩ひとつまみ','podle chuti':'好みの量','minut':'分','hodin':'時間','v lednici':'冷蔵庫で','na 180 °C':'180°Cで','na 170 °C':'170°Cで'};let out=s;for(const [a,b] of Object.entries(lang==='en'?dictEn:dictJa))out=out.replaceAll(a,b);return out}
function familyNutritionLegacy(r){return {kcal:Math.round(r.kcal*1.12),p:Math.max(3,Math.round(r.p*.58)),c:Math.round(r.c*1.35),f:Math.round(r.f*1.1),fiber:r.fiber}}
function macros(r){const n=family?familyNutrition(r):r;return [[t('kcal'),n.kcal],[t('protein'),n.p+' g'],[t('carbs'),n.c+' g'],[t('fat'),n.f+' g'],[t('fiber'),n.fiber+' g']].map(x=>`<div class="macro"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('')}
function applyLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(e=>e.placeholder=t(e.dataset.i18nPlaceholder));document.getElementById('search').placeholder=t('search');document.getElementById('language').value=lang;document.getElementById('modeText').textContent=family?t('family'):t('fitness');const cs=document.getElementById('cloudStatus');if(cs)cs.textContent=cloudUser?t('cloudConnected'):t('cloudLocal');buildSelects();render()}
function buildSelects(){const ch=document.getElementById('chapter'),current=ch.value||'all';ch.innerHTML=`<option value="all">${t('all')}</option>`;[...new Set(allRecipes().map(r=>r.chapter))].forEach(c=>ch.insertAdjacentHTML('beforeend',`<option value="${c}">${chapterName(c)}</option>`));ch.value=[...ch.options].some(o=>o.value===current)?current:'all';const sort=document.getElementById('sort'),sv=sort.value;sort.innerHTML=`<option value="default">${t('sortDefault')}</option><option value="kcal">${t('sortKcal')}</option><option value="kcalHigh">${t('sortKcalHigh')}</option><option value="protein">${t('sortProtein')}</option><option value="proteinLow">${t('sortProteinLow')}</option><option value="fiber">${t('sortFiber')}</option><option value="carbs">${t('sortCarbs')}</option><option value="fat">${t('sortFat')}</option><option value="time">${t('sortTime')}</option><option value="cost">${t('sortCost')}</option><option value="costHigh">${t('sortCostHigh')}</option>`;sort.value=sv||'default';const fc=document.getElementById('fChapter');fc.innerHTML=[...new Set(baseRecipes.map(r=>r.chapter))].map(c=>`<option value="${c}">${chapterName(c)}</option>`).join('')}
function nutritionFor(r){return family?familyNutrition(r):r}
function filteredLegacy(){let q=document.getElementById('search').value.toLowerCase(),ch=document.getElementById('chapter').value,arr=allRecipes();if(view==='favorites')arr=arr.filter(r=>favs().includes(r.id));if(view==='custom')arr=arr.filter(r=>r.custom);arr=arr.filter(r=>(ch==='all'||r.chapter===ch)&&([r.name,r.flavor,r.kind,...r.ingredients].join(' ').toLowerCase().includes(q)));if(activeFilter==='under150')arr=arr.filter(r=>nutritionFor(r).kcal<=150);if(activeFilter==='lowcal')arr=arr.filter(r=>nutritionFor(r).kcal<=200);if(activeFilter==='highprotein')arr=arr.filter(r=>nutritionFor(r).p>=20);if(activeFilter==='protein30')arr=arr.filter(r=>nutritionFor(r).p>=30);if(activeFilter==='highfiber')arr=arr.filter(r=>nutritionFor(r).fiber>=7);if(activeFilter==='lowcarb')arr=arr.filter(r=>nutritionFor(r).c<=25);if(activeFilter==='lowfat')arr=arr.filter(r=>nutritionFor(r).f<=5);if(activeFilter==='cheap')arr=arr.filter(r=>r.cost<=200);if(activeFilter==='family')arr=arr.filter(r=>(r.familySwap||[]).length>0);if(activeFilter==='quick')arr=arr.filter(r=>(parseInt(r.time)||99)<=15);if(activeFilter==='mealprep')arr=arr.filter(r=>r.prep&&r.prep.length>4);const so=document.getElementById('sort').value;const n=r=>nutritionFor(r);if(so==='kcal')arr.sort((a,b)=>n(a).kcal-n(b).kcal);if(so==='kcalHigh')arr.sort((a,b)=>n(b).kcal-n(a).kcal);if(so==='protein')arr.sort((a,b)=>n(b).p-n(a).p);if(so==='proteinLow')arr.sort((a,b)=>n(a).p-n(b).p);if(so==='fiber')arr.sort((a,b)=>n(b).fiber-n(a).fiber);if(so==='carbs')arr.sort((a,b)=>n(a).c-n(b).c);if(so==='fat')arr.sort((a,b)=>n(a).f-n(b).f);if(so==='time')arr.sort((a,b)=>(parseInt(a.time)||999)-(parseInt(b.time)||999));if(so==='cost')arr.sort((a,b)=>a.cost-b.cost);if(so==='costHigh')arr.sort((a,b)=>b.cost-a.cost);return arr}

function shoppingText(row,index){if(lang==='cs')return row;if(lang==='en'){const enNames=['Oikos and protein yogurts','Okara powder','Silken tofu','Natto','Konjac and shirataki','Edamame','Chicken breast','Mackerel','Frozen blueberries','Cottage cheese','Protein powder','Psyllium','Erythritol','Oat flour','Greek yogurt'];return [enNames[index]||row[0],row[1],row[2],trLine(row[3])]}const jaNames=['オイコス・高たんぱくヨーグルト','おからパウダー','絹ごし豆腐','納豆','こんにゃく・しらたき','枝豆','鶏むね肉','さば','冷凍ブルーベリー','カッテージチーズ','プロテインパウダー','サイリウム','エリスリトール','オートミール粉','ギリシャヨーグルト'];const places=['AEON、Costco、SEIYU、コンビニ','AEON、業務スーパー、ドン・キホーテ、Amazon Japan','スーパー、コンビニ','スーパー','スーパー','冷凍食品売り場、業務スーパー、Costco','業務スーパー、AEON、SEIYU','スーパー、さば水煮缶','Costco、業務スーパー、AEON','AEON、SEIYU、イトーヨーカドー、Costco（一部店舗）','ドン・キホーテ、マツモトキヨシ、Amazon、iHerb','Amazon Japan、iHerb、一部ドラッグストア','Amazon、iHerb、大型スーパー','オートミールをミキサーで粉にするか、オンラインで購入','AEON、SEIYU、Costco、コンビニ'];const tips=['プレーン・無糖、または糖質が少ない商品を選びます。','お菓子作りには粉末タイプが便利です。生おからは水分が多いので分量調整が必要です。','デザートにはなめらかな絹ごし豆腐が向いています。','和風の高たんぱく朝食に便利です。付属のたれの量に注意してください。','低カロリーの付け合わせですが、たんぱく質源の代わりにはなりません。','塩分が少ないものを選びます。','安価で使いやすいたんぱく質源です。まとめて調理できます。','水煮缶は作り置きに便利です。','生の果物より安く買えることがあります。','見つからない場合は水切りギリシャヨーグルトや、なめらかにした豆腐で代用できます。','バニラ味が最も使いやすく、塩味レシピには無味タイプが向いています。','水分をすぐ吸うため、少量ずつ加えてください。','少量から加えて味を確認してください。','普通のオートミールをミキサーで粉にするのが最も安価です。','プレーン無糖タイプが最も使いやすいです。'];return [jaNames[index],row[1],places[index],tips[index]]}

function render(){const all=allRecipes();document.getElementById('totalRecipes').textContent=all.length;const root=document.getElementById('content');root.innerHTML='';const arr=filtered();if(!arr.length){root.innerHTML=`<div class="empty">${view==='favorites'?t('noFavorites'):view==='custom'?t('noCustom'):t('noResults')}</div>`;return}const groups={};arr.forEach(r=>(groups[r.chapter]??=[]).push(r));for(const [ch,rs] of Object.entries(groups)){const sec=document.createElement('section');sec.innerHTML=`<div class="chapter-head"><h2>${chapterName(ch)}</h2><span>${rs.length} ${t('recipes')}</span></div><div class="grid"></div>`;const grid=sec.querySelector('.grid');for(const r of rs){const card=document.createElement('article');card.className='card';card.innerHTML=`<div class="photo"><img loading="lazy" src="${imageFor(r)}" alt="${translateName(r.name)}"><span class="emoji">${r.emoji}</span>${r.custom?`<span class="custom-badge">${t('custom')}</span>`:''}<div class="version-badges"><span class="version-badge fitness ${family?'inactive':''}">${t('fitness')}</span>${(r.familySwap||[]).length?`<span class="version-badge family ${family?'':'inactive'}">${t('family')}</span>`:''}</div></div><div class="body"><h3>${translateName(r.name)}</h3><div class="meta"><span>⏱ ${r.time}</span><span>📊 ${trLine(r.diff)}</span><span>💴 ¥${r.cost}</span></div><div class="macros">${macros(r)}</div><div class="actions"><button class="btn primary" data-open="${r.id}">${t('open')}</button><button class="btn fav" data-fav="${r.id}">${favs().includes(r.id)?'♥':'♡'}</button></div></div>`;grid.appendChild(card)}root.appendChild(sec)}if(view==='all'){const guide=document.createElement('section');guide.innerHTML=`<div class="chapter-head"><h2>10. ${t('shopping')}</h2><span>${shopping.length} ${t('items')}</span></div><div class="guide">${shopping.map((s,i)=>{const z=shoppingText(s,i);return `<article class="guide-card"><h3>${z[0]}</h3><div class="jp">${z[1]}</div><p><b>${t('where')}:</b> ${z[2]}</p><p>${z[3]}</p></article>`}).join('')}</div>`;root.appendChild(guide)}bindCards()}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecipe(+b.dataset.open));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let a=favs(),id=+b.dataset.fav;a=a.includes(id)?a.filter(x=>x!==id):[...a,id];localStorage.setItem('cookFav',JSON.stringify(a));if(cloudState)cloudState.favorites=a;cloudChanged();render()})}
function openRecipe(id){const r=allRecipes().find(x=>x.id===id);if(!r)return;currentId=id;document.getElementById('mTitle').textContent=r.emoji+' '+translateName(r.name);document.getElementById('mMeta').innerHTML=`<span class="detail-version ${family?'family':'fitness'}">${family?t('family'):t('fitness')}</span><span>⏱ ${r.time}</span><span>📊 ${trLine(r.diff)}</span><span>🍽️ ${t('portion')}</span>`;document.getElementById('mImage').src=imageFor(r);document.getElementById('mMacros').innerHTML=macros(r);let ing=[...r.ingredients];if(family)ing=ing.filter(x=>!x.toLowerCase().includes('protein')).concat(r.familySwap||[]);document.getElementById('mIngredients').innerHTML=ing.map((x,i)=>`<li><label class="ingredient-check"><input type="checkbox" data-ing="${i}"><span>${trLine(x)}</span></label></li>`).join('');document.getElementById('mSteps').innerHTML=r.steps.map(x=>`<li>${trLine(x)}</li>`).join('');document.getElementById('mStores').textContent=trLine(r.stores||'');document.getElementById('mCost').textContent='¥'+r.cost;document.getElementById('mPrep').textContent=trLine(r.prep||'');document.getElementById('mFreeze').textContent=trLine(r.freeze||'');document.getElementById('mKeep').textContent=trLine(r.keep||'');document.getElementById('mFamily').textContent=trLine((r.familySwap||[]).join(' '));document.getElementById('editCustom').style.display=r.custom?'inline-flex':'none';document.getElementById('deleteCustom').style.display=r.custom?'inline-flex':'none';document.getElementById('removePhoto').style.display=photoOverrides()[r.id]?'inline-flex':'none';document.getElementById('detailFav').textContent=favs().includes(r.id)?'♥':'♡';document.getElementById('recipeModal').classList.add('open')}
function closeModal(id){document.getElementById(id).classList.remove('open')}
async function resizeImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.82))};img.onerror=reject;img.src=url})}
async function resizeImageBlob(file){return await dataUrlToBlob(await resizeImage(file))}
function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
function openForm(r=null){document.getElementById('formTitle').textContent=r?t('editRecipe'):t('newRecipe');document.getElementById('editId').value=r?.id||'';document.getElementById('fName').value=r?.name||'';document.getElementById('fChapter').value=r?.chapter||baseRecipes[0].chapter;document.getElementById('fEmoji').value=r?.emoji||'🍽️';document.getElementById('fTime').value=r?.time||'20 min';document.getElementById('fDiff').value=r?.diff||'';document.getElementById('fCost').value=r?.cost||200;document.getElementById('fKcal').value=r?.kcal||'';document.getElementById('fP').value=r?.p||'';document.getElementById('fC').value=r?.c||'';document.getElementById('fF').value=r?.f||'';document.getElementById('fFiber').value=r?.fiber||0;document.getElementById('fIngredients').value=(r?.ingredients||[]).join('\n');document.getElementById('fSteps').value=(r?.steps||[]).join('\n');document.getElementById('fStores').value=r?.stores||'';document.getElementById('fPrep').value=r?.prep||'';document.getElementById('fFreeze').value=r?.freeze||'';document.getElementById('fKeep').value=r?.keep||'';document.getElementById('fFamily').value=(r?.familySwap||[]).join('\n');document.getElementById('fPhoto').value='';document.getElementById('formModal').classList.add('open')}
document.getElementById('recipeForm').onsubmit=async e=>{e.preventDefault();const oldId=+document.getElementById('editId').value;let list=customRecipes();const id=oldId||Date.now();const r={id,custom:true,name:document.getElementById('fName').value.trim(),chapter:document.getElementById('fChapter').value,emoji:document.getElementById('fEmoji').value||'🍽️',kind:'Snídaně',flavor:'custom',kcal:+document.getElementById('fKcal').value,p:+document.getElementById('fP').value,c:+document.getElementById('fC').value,f:+document.getElementById('fF').value,fiber:+document.getElementById('fFiber').value,time:document.getElementById('fTime').value,diff:document.getElementById('fDiff').value,cost:+document.getElementById('fCost').value,stores:document.getElementById('fStores').value,prep:document.getElementById('fPrep').value,freeze:document.getElementById('fFreeze').value,keep:document.getElementById('fKeep').value,ingredients:document.getElementById('fIngredients').value.split('\n').map(x=>x.trim()).filter(Boolean),steps:document.getElementById('fSteps').value.split('\n').map(x=>x.trim()).filter(Boolean),familySwap:document.getElementById('fFamily').value.split('\n').map(x=>x.trim()).filter(Boolean),image:''};list=oldId?list.map(x=>x.id===oldId?r:x):[r,...list];localStorage.setItem('cookCustom',JSON.stringify(list));if(cloudState)cloudState.custom_recipes=list;cloudChanged();const file=document.getElementById('fPhoto').files[0];if(file){try{if(cloudUser)await uploadPhotoToStorage(id,await resizeImageBlob(file));else setPhotoOverride(id,await resizeImage(file))}catch(err){console.error(err);toast('Photo upload error')}}closeModal('formModal');buildSelects();render();openRecipe(id)};
document.getElementById('recipePhoto').onchange=async e=>{const file=e.target.files[0];if(!file||!currentId)return;try{if(cloudUser)await uploadPhotoToStorage(currentId,await resizeImageBlob(file));else setPhotoOverride(currentId,await resizeImage(file));document.getElementById('mImage').src=imageFor(allRecipes().find(r=>r.id===currentId));document.getElementById('removePhoto').style.display='inline-flex';render();toast(t('photoSaved'))}catch(err){console.error(err);toast('Image upload error')}e.target.value=''};
document.getElementById('removePhoto').onclick=async()=>{if(!currentId)return;const old=photoOverrides()[currentId],path=photoPath(old);if(path&&sb&&cloudUser){const {error}=await sb.storage.from(PHOTO_BUCKET).remove([path]);if(error){console.error(error);toast('Photo delete error');return}}delete photoUrlCache[currentId];setPhotoOverride(currentId,null);const r=allRecipes().find(x=>x.id===currentId);document.getElementById('mImage').src=imageFor(r);document.getElementById('removePhoto').style.display='none';render()};
document.getElementById('editCustom').onclick=()=>{const r=customRecipes().find(x=>x.id===currentId);closeModal('recipeModal');openForm(r)};
document.getElementById('deleteCustom').onclick=async()=>{if(!confirm(t('confirmDelete')))return;const old=photoOverrides()[currentId],path=photoPath(old);if(path&&sb&&cloudUser)await sb.storage.from(PHOTO_BUCKET).remove([path]);delete photoUrlCache[currentId];const nextCustom=customRecipes().filter(x=>x.id!==currentId);localStorage.setItem('cookCustom',JSON.stringify(nextCustom));if(cloudState)cloudState.custom_recipes=nextCustom;cloudChanged();setPhotoOverride(currentId,null);closeModal('recipeModal');buildSelects();render()};
document.getElementById('addRecipe').onclick=()=>openForm();document.getElementById('closeRecipe').onclick=()=>closeModal('recipeModal');document.getElementById('closeForm').onclick=()=>closeModal('formModal');document.getElementById('cancelForm').onclick=()=>closeModal('formModal');document.getElementById('recipeModal').onclick=e=>{if(e.target.id==='recipeModal')closeModal('recipeModal')};document.getElementById('formModal').onclick=e=>{if(e.target.id==='formModal')closeModal('formModal')};
document.getElementById('modeSwitch').onclick=e=>{family=!family;e.currentTarget.classList.toggle('on',family);document.getElementById('modeText').textContent=family?t('family'):t('fitness');render()};document.getElementById('language').onchange=e=>{lang=e.target.value;localStorage.setItem('cookLang',lang);if(cloudState)cloudState.language=lang;cloudChanged();applyLanguage()};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));render()});['search','chapter','sort'].forEach(id=>document.getElementById(id).addEventListener('input',render));document.getElementById('random').onclick=()=>{const a=filtered();if(a.length)openRecipe(a[Math.floor(Math.random()*a.length)].id)};
function setAuthBusy(busy,label=''){['signInBtn','signUpBtn','resendBtn','resetPasswordBtn'].forEach(id=>{const b=document.getElementById(id);if(b)b.disabled=busy});if(label)setAuthMessage(label,'info')}
function authInputs(){return {email:document.getElementById('authEmail').value.trim().toLowerCase(),password:document.getElementById('authPassword').value,confirm:document.getElementById('authPasswordConfirm').value}}
function validEmail(email){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)}
document.getElementById('cloudBtn').onclick=async()=>{document.getElementById('authModal').classList.add('open');const signed=!!cloudUser;document.getElementById('signOutBtn').style.display=signed?'inline-flex':'none';document.getElementById('signInBtn').style.display=signed?'none':'inline-flex';document.getElementById('signUpBtn').style.display=signed?'none':'inline-flex';document.getElementById('resetPasswordBtn').style.display=signed?'none':'inline-flex';document.getElementById('confirmPasswordField').style.display='none';document.getElementById('resendBtn').style.display='none';if(signed)setAuthMessage(t('signedAs')+' '+cloudUser.email+'.','info');else if(!supabaseConfigured())setAuthMessage(t('missingConfig'),'error');else if(!sb){setAuthMessage(t('connecting'),'info');await initSupabase();if(sb)setAuthMessage(t('authPrompt'),'info')}else setAuthMessage(t('authPrompt'),'info')};
document.getElementById('closeAuth').onclick=()=>closeModal('authModal');
document.getElementById('signInBtn').onclick=async()=>{try{if(!sb)await initSupabase();if(!sb)throw new Error(msg('Supabase klient není dostupný','Supabase client is unavailable','Supabaseクライアントを利用できません'));const {email,password}=authInputs();if(!validEmail(email))throw new Error(msg('Zadej platný e-mail.','Enter a valid email address.','有効なメールアドレスを入力してください。'));if(password.length<6)throw new Error(msg('Heslo musí mít alespoň 6 znaků.','Password must contain at least 6 characters.','パスワードは6文字以上にしてください。'));setAuthBusy(true,msg('Přihlašuji…','Signing in…','ログインしています…'));const {data,error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;cloudUser=data.user||data.session?.user||null;setAuthMessage(msg('Přihlášení proběhlo úspěšně.','Signed in successfully.','ログインしました。'),'info');if(cloudUser){await loadCloudState();setTimeout(()=>closeModal('authModal'),450)}}catch(e){const msg=friendlyAuthError(e);setAuthMessage(msg,'error');if((e?.message||'').toLowerCase().includes('email not confirmed'))document.getElementById('resendBtn').style.display='inline-flex'}finally{setAuthBusy(false)}};
document.getElementById('signUpBtn').onclick=async()=>{try{if(!sb)await initSupabase();if(!sb)throw new Error(msg('Supabase klient není dostupný','Supabase client is unavailable','Supabaseクライアントを利用できません'));const confirmField=document.getElementById('confirmPasswordField');if(confirmField.style.display==='none'){confirmField.style.display='flex';setAuthMessage(msg('Zopakuj heslo a potom znovu klepni na Vytvořit účet.','Repeat the password, then tap Create account again.','パスワードを再入力して、もう一度「アカウント作成」をタップしてください。'),'info');return}const {email,password,confirm}=authInputs();if(!validEmail(email))throw new Error(msg('Zadej platný e-mail.','Enter a valid email address.','有効なメールアドレスを入力してください。'));if(password.length<6)throw new Error(msg('Heslo musí mít alespoň 6 znaků.','Password must contain at least 6 characters.','パスワードは6文字以上にしてください。'));if(password!==confirm)throw new Error(msg('Hesla se neshodují.','Passwords do not match.','パスワードが一致しません。'));setAuthBusy(true,msg('Vytvářím účet…','Creating account…','アカウントを作成しています…'));const options={};const redirect=authBaseUrl();if(redirect)options.emailRedirectTo=redirect;const {data,error}=await sb.auth.signUp({email,password,options});if(error)throw error;if(data.session){cloudUser=data.user;setAuthMessage(msg('Účet byl vytvořen a jsi přihlášen.','Your account was created and you are signed in.','アカウントを作成し、ログインしました。'),'info');await loadCloudState();setTimeout(()=>closeModal('authModal'),600)}else{setAuthMessage(msg('Účet byl vytvořen. Zkontroluj e-mail a potvrď registraci. Potom se přihlas.','Your account was created. Confirm it from your email, then sign in.','アカウントを作成しました。確認メールのリンクを開いてからログインしてください。'),'info');document.getElementById('resendBtn').style.display='inline-flex'}}catch(e){setAuthMessage(friendlyAuthError(e),'error')}finally{setAuthBusy(false)}};
document.getElementById('resendBtn').onclick=async()=>{try{if(!sb)throw new Error(msg('Supabase klient není dostupný','Supabase client is unavailable','Supabaseクライアントを利用できません'));const {email}=authInputs();if(!validEmail(email))throw new Error(msg('Zadej platný e-mail.','Enter a valid email address.','有効なメールアドレスを入力してください。'));setAuthBusy(true,'Odesílám potvrzovací e-mail…');const options={};const redirect=authBaseUrl();if(redirect)options.emailRedirectTo=redirect;const {error}=await sb.auth.resend({type:'signup',email,options});if(error)throw error;setAuthMessage(msg('Potvrzovací e-mail byl znovu odeslán.','The confirmation email was sent again.','確認メールを再送しました。'),'info')}catch(e){setAuthMessage(friendlyAuthError(e),'error')}finally{setAuthBusy(false)}};
document.getElementById('resetPasswordBtn').onclick=async()=>{try{if(!sb)await initSupabase();if(!sb)throw new Error(msg('Supabase klient není dostupný','Supabase client is unavailable','Supabaseクライアントを利用できません'));const {email}=authInputs();if(!validEmail(email))throw new Error('Nejdřív zadej platný e-mail.');setAuthBusy(true,'Odesílám odkaz pro změnu hesla…');const redirect=authBaseUrl();const {error}=await sb.auth.resetPasswordForEmail(email,redirect?{redirectTo:redirect}:undefined);if(error)throw error;setAuthMessage(msg('Odkaz pro změnu hesla byl odeslán na e-mail.','A password reset link was sent by email.','パスワード再設定リンクをメールで送信しました。'),'info')}catch(e){setAuthMessage(friendlyAuthError(e),'error')}finally{setAuthBusy(false)}};
document.getElementById('signOutBtn').onclick=async()=>{try{if(sb)await sb.auth.signOut();setAuthMessage(msg('Odhlášeno.','Signed out.','ログアウトしました。'),'info');setTimeout(()=>closeModal('authModal'),350)}catch(e){setAuthMessage(friendlyAuthError(e),'error')}};

// Practical navigation, filters, favorites and cooking mode
function setView(next){view=next;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===next));document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.nav===next));render();window.scrollTo({top:0,behavior:'smooth'})}
// v9 filters bound after DOMContentLoaded
