function ingredientAmount(text){
 const s=String(text).replace(',','.'); const m=s.match(/(\d+(?:\.\d+)?)\s*(kg|g|ml|l|ks|kus|vejce|egg|個|本|lžíce|lžička|tbsp|tsp)?/i);
 if(!m){if(/banán|banana|バナナ/i.test(s))return 120;if(/jabl|apple|りんご/i.test(s))return 150;if(/vejce|egg|卵/i.test(s))return 50;return 10}
 let n=+m[1],u=(m[2]||'g').toLowerCase();if(u==='kg'||u==='l')n*=1000;if(/ks|kus|vejce|egg|個|本/.test(u))n*=50;if(/lžíce|tbsp/.test(u))n*=15;if(/lžička|tsp/.test(u))n*=5;return n;
}
function rawIngredientNutrition(text){const hit=INGREDIENT_DB.find(([re])=>re.test(text));const per=hit?hit[1]:{kcal:250,p:5,c:40,f:7,fiber:3};const factor=ingredientAmount(text)/100;return Object.fromEntries(Object.entries(per).map(([k,v])=>[k,v*factor]));}
function ingredientNutritionBreakdown(r,ingredients){
 const total=nutritionFor(r);const raws=ingredients.map(rawIngredientNutrition);const keys=['kcal','p','c','f','fiber'];
 const out=raws.map(x=>({...x}));for(const key of keys){const sum=raws.reduce((a,x)=>a+(x[key]||0),0);for(let i=0;i<out.length;i++)out[i][key]=sum>0?(raws[i][key]||0)/sum*(total[key]||0):(total[key]||0)/Math.max(1,out.length)}
 return out;
}
function fmtN(v,key){return key==='kcal'?Math.round(v):Math.round(v*10)/10}
function nutritionCells(n){return `<div class="ingredient-nutri-grid"><div class="ingredient-nutri-cell"><b>${fmtN(n.kcal,'kcal')}</b><small>kcal</small></div><div class="ingredient-nutri-cell"><b>${fmtN(n.p)} g</b><small>${t('protein')}</small></div><div class="ingredient-nutri-cell"><b>${fmtN(n.c)} g</b><small>${t('carbs')}</small></div><div class="ingredient-nutri-cell"><b>${fmtN(n.f)} g</b><small>${t('fat')}</small></div><div class="ingredient-nutri-cell"><b>${fmtN(n.fiber)} g</b><small>${t('fiber')}</small></div></div>`}
const openRecipeV10=openRecipe;
openRecipe=function(id){
 openRecipeV10(id);const r=allRecipes().find(x=>x.id===id);if(!r)return;let ing=[...(r.ingredients||[])];if(family)ing=ing.filter(x=>!x.toLowerCase().includes('protein')).concat(r.familySwap||[]);const breakdown=ingredientNutritionBreakdown(r,ing),total=nutritionFor(r),root=document.getElementById('mIngredients');
 root.innerHTML=ing.map((x,i)=>{const n=breakdown[i],share=total.p?Math.round(n.p/total.p*100):0;return `<li class="ingredient-nutrition"><div class="ingredient-main"><input type="checkbox" data-ing="${i}"><div><div class="ingredient-name">${escapeHtml(trLine(x))}</div><div class="ingredient-compact">${fmtN(n.kcal,'kcal')} kcal · ${fmtN(n.p)} g ${t('protein')}</div></div><button class="ingredient-expand" type="button" aria-label="${t('ingredientNutrition')}">⌄</button></div><div class="ingredient-details">${nutritionCells(n)}<div class="protein-share">${t('proteinShare')}: ${share}%</div></div></li>`}).join('');
 root.querySelectorAll('.ingredient-expand').forEach(b=>b.onclick=()=>{const li=b.closest('.ingredient-nutrition');li.classList.toggle('open');b.textContent=li.classList.contains('open')?'⌃':'⌄'});
 const box=document.createElement('div');box.className='ingredient-total-box';box.innerHTML=`<div class="ingredient-total-title">${t('recipeTotal')}</div><div class="ingredient-total-grid"><span><b>${total.kcal}</b>kcal</span><span><b>${total.p} g</b>${t('protein')}</span><span><b>${total.c} g</b>${t('carbs')}</span><span><b>${total.f} g</b>${t('fat')}</span><span><b>${total.fiber||0} g</b>${t('fiber')}</span></div><div class="ingredient-estimate-note">${t('ingredientEstimate')}</div>`;root.after(box);
 const old=root.parentElement.querySelectorAll('.ingredient-total-box');if(old.length>1)old[0].remove();
}
